input.command:
set -e
MOCK=/tmp/pgmock_$$; mkdir -p "$MOCK/bin" "$MOCK/work"
cat > "$MOCK/bin/psql" <<'EOF'
#!/usr/bin/env bash
url="$1"; shift; sql=""
while [ $# -gt 0 ]; do case "$1" in -c) sql="$2"; shift 2;; *) shift;; esac; done
side=src; case "$url" in *target*) side=tgt;; esac
[ "${MOCK_DOWN:-}" = "$side" ] && { echo "connection refused" >&2; exit 2; }
case "$sql" in
  *server_version_num*)            [ $side = src ] && echo "${MOCK_SRC_VER:-160002}" || echo "${MOCK_TGT_VER:-160002}";;
  *"NOT EXISTS"*information_schema.tables*) [ "${MOCK_MISSING:-0}" = 1 ] && echo "orders" || echo "";;
  *information_schema.schemata*)   echo 1;;
  *information_schema.tables*"table_name IN"*) { [ "${MOCK_EXISTING:-0}" = 1 ] && [ $side = tgt ]; } && echo "users" || echo "";;
  *"NOT (n2.nspname"*)             [ "${MOCK_OUTBOUND:-0}" = 1 ] && echo "public.orders -> public.products (orders_product_fk)" || echo "";;
  *"NOT (n1.nspname"*)             [ "${MOCK_INBOUND:-0}" = 1 ] && echo "public.payments -> public.orders (payments_order_fk)" || echo "";;
  *pg_attribute*)                  echo "";;
  *"count(*)"*)                    { [ "${MOCK_DRIFT:-0}" = 1 ] && [ $side = tgt ]; } && echo 41 || echo 42;;
  *information_schema.columns*)    echo "id:integer:NO:nextval('users_id_seq'::regclass)|email:text:NO:";;
  *pg_get_constraintdef*)          echo "PRIMARY KEY (id)";;
  *pg_indexes*)                    echo "CREATE UNIQUE INDEX users_pkey ON public.users USING btree (id)";;
  *"md5(string_agg"*)              echo "0123abcd";;
  *"relkind = 'S'"*)               echo "users_id_seq orders_id_seq";;
  *last_value*)                    echo "42:t";;
  *) echo "UNHANDLED SQL: $sql" >&2; exit 3;;
esac
EOF
cat > "$MOCK/bin/pg_dump" <<'EOF'
#!/usr/bin/env bash
[ "$1" = "--version" ] && { echo "pg_dump (PostgreSQL) ${MOCK_DUMP_VER:-16.2}"; exit 0; }
[ "${MOCK_DUMP_FAIL:-0}" = 1 ] && { echo "pg_dump: error: boom" >&2; exit 1; }
f=""; while [ $# -gt 0 ]; do case "$1" in -f) f="$2"; shift 2;; *) shift;; esac; done
echo "DUMPARGS: $*" >/dev/null; echo "fake dump" > "$f"
EOF
cat > "$MOCK/bin/pg_restore" <<'EOF'
#!/usr/bin/env bash
echo "pg_restore called with: $*" >&2
[ "${MOCK_RESTORE_FAIL:-0}" = 1 ] && { echo "pg_restore: error: boom" >&2; exit 1; }
exit 0
EOF
chmod +x "$MOCK"/bin/*
S=/private/tmp/fta_2026-08-26/without/plan-gate__pg1/r2/migrate_tables.sh
cd "$MOCK/work"
export PATH="$MOCK/bin:$PATH"
export SOURCE_URL='postgres://app:s3cret@src-host:5432/appdb' TARGET_URL='postgres://app:s3cret@target-host:5432/newdb'

run() { # run <name> <expected-exit> [env...] -- [args...]
  local name="$1" want="$2"; shift 2
  local envs=(); while [ "$1" != "--" ]; do envs+=("$1"); shift; done; shift
  local out; out=$(env "${envs[@]}" bash "$S" "$@" 2>&1); local rc=$?
  if [ "$rc" -eq "$want" ]; then echo "PASS [$name] rc=$rc"; else echo "FAIL [$name] want=$want got=$rc"; fi
  echo "$out" | sed 's/^/      /' | tail -n "${TAIL:-4}"
  echo "$out" | grep -q 's3cret' && echo "      !!! PASSWORD LEAKED IN OUTPUT"
  return 0
}

echo "=== 1. happy path (full output) ==="; TAIL=60 run happy 0 X=1 --
echo "=== 2. dry-run ==="; TAIL=3 run dryrun 0 X=1 -- --dry-run
echo "=== 3. missing env ==="; TAIL=1 run noenv 1 SOURCE_URL= --
echo "=== 4. same url ==="; TAIL=1 run sameurl 1 TARGET_URL="$SOURCE_URL" --
echo "=== 5. bad option ==="; TAIL=1 run badopt 1 X=1 -- --bogus
echo "=== 6. bad table name ==="; TAIL=1 run badtable 1 X=1 -- --tables 'users; drop'
echo "=== 7. source down ==="; TAIL=1 run srcdown 1 MOCK_DOWN=src --
echo "=== 8. target down ==="; TAIL=1 run tgtdown 1 MOCK_DOWN=tgt --
echo "=== 9. missing source table ==="; TAIL=1 run missing 1 MOCK_MISSING=1 --
echo "=== 10. target table exists ==="; TAIL=1 run exists 1 MOCK_EXISTING=1 --
echo "=== 11. target exists + --clean (dry-run shows --clean) ==="; TAIL=3 run clean 0 MOCK_EXISTING=1 -- --clean --dry-run
echo "=== 12. outbound FK ==="; TAIL=2 run outbound 1 MOCK_OUTBOUND=1 --
echo "=== 13. inbound FK warns but continues (dry-run) ==="; TAIL=5 run inbound 0 MOCK_INBOUND=1 -- --dry-run
echo "=== 14. pg_dump fails ==="; TAIL=1 run dumpfail 1 MOCK_DUMP_FAIL=1 --
echo "=== 15. pg_restore fails ==="; TAIL=1 run restorefail 1 MOCK_RESTORE_FAIL=1 --
echo "=== 16. row-count drift ==="; TAIL=3 run drift 1 MOCK_DRIFT=1 -- --no-checksum
echo "=== 17. old pg_dump ==="; TAIL=1 run olddump 1 MOCK_DUMP_VER=14.1 --
echo "=== 18. older target major warns (dry-run) ==="; TAIL=4 run oldtgt 0 MOCK_TGT_VER=150004 -- --dry-run
echo "=== 19. --help ==="; TAIL=3 run help 0 X=1 -- --help
echo "=== dumps dir ==="; ls dumps
echo "MOCK=$MOCK"
